// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {CVXStaker, IERC20, ICVXBooster} from "../src/CVXStaker.sol";

contract InvMutTest is Test {
    CVXStaker c;
    function setUp() public {
        __InvMutHandleStub stub = new __InvMutHandleStub();
        c = new CVXStaker(address(new __InvMutHandleStub()), IERC20(address(stub)), ICVXBooster(address(stub)), new address[](0));
    }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // owner (deployer = this test contract) transfers ownership to a fresh actor
        c.transferOwnership(actor);
        // the previous owner must no longer hold any ownership privilege
        bool ok;
        try c.setOperator(address(0x1234)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "previous owner must lose ownership privileges after transferOwnership");
    }
}
contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
